<!--
  Ficheiro: src/components/iptv/StreamPlayerDialog.vue
  Tipo: Player modal Vue.
  Função: Reproduz HTTP/áudio/HLS nativo e explica formatos incompatíveis.
-->
<script setup lang="ts">
import { computed,ref,watch } from "vue";import type { ChannelRecord,StreamLinkRecord } from "@/types/records";import { selectPrimaryLink } from "@/domain/iptv/selectPrimaryLink";
const props=defineProps<{channel:ChannelRecord|null;links:StreamLinkRecord[];open:boolean}>();const emit=defineEmits<{close:[]}>();const customSource=ref<string>("");const selection=computed(()=>props.channel?selectPrimaryLink(props.channel,props.links):{selected:null,alternatives:[]});const sources=computed(()=>selection.value.selected?[selection.value.selected,...selection.value.alternatives]:[]);const source=computed(()=>sources.value.find(x=>x.url===customSource.value)||selection.value.selected);watch(()=>props.open,open=>{if(open)customSource.value=selection.value.selected?.url||""});const isAudio=computed(()=>source.value?.type==="audio");const playable=computed(()=>source.value&&!source.value.requiresBackend&&["http","audio","hls"].includes(source.value.type));
</script>
<template><Teleport to="body"><div v-if="open&&channel" class="dialog-backdrop" @click.self="emit('close')"><section class="dialog-panel stream-player" role="dialog" aria-modal="true" aria-labelledby="stream-player-title" @keydown.esc="emit('close')"><div class="dialog-header"><div><p class="eyebrow">Reprodução em direto</p><h2 id="stream-player-title">{{channel.nome}}</h2></div><button class="icon-button" type="button" aria-label="Fechar player" @click="emit('close')">×</button></div><label v-if="sources.length>1" class="form-field"><span>Fonte</span><select v-model="customSource"><option v-for="item in sources" :key="item.url" :value="item.url">{{item.label}} · {{item.type.toUpperCase()}}</option></select></label><p v-if="source?.requiresBackend" class="form-alert form-alert-error" role="alert">Esta fonte requer cabeçalhos especiais ou um protocolo que o navegador não suporta. Usa o backend local.</p><p v-else-if="!playable" class="form-alert" role="status">Não existe uma fonte reproduzível diretamente no navegador.</p><audio v-else-if="isAudio" class="stream-media" controls autoplay :src="source?.url"/><video v-else class="stream-media" controls autoplay playsinline :src="source?.url">O navegador não suporta vídeo HTML5.</video><p v-if="source?.type==='hls'" class="field-hint">HLS funciona nativamente apenas em navegadores compatíveis. A integração com hls.js fica para o próximo incremento.</p></section></div></Teleport></template>
